// Some portions generated by Co-Pilot
const ADOPTIUM_API = "https://api.adoptium.net/v3";
const PAGE_SIZE = 5; // Keep full release responses below Next.js's 2 MB cache limit.

export interface PlatformBreakdownRow {
  version: number;
  os: string;
  architecture: string;
  imageType: string;
  archive: number;
  installer: number;
}

export interface PlatformBreakdownStats {
  rows: PlatformBreakdownRow[];
}

interface ReleaseAsset {
  binaries: Array<{
    os: string;
    architecture: string;
    image_type: string;
    package?: { download_count?: number };
    installer?: { download_count?: number };
  }>;
}

async function fetchJson<T>(url: string): Promise<T | null> {
  const res = await fetch(url, { next: { revalidate: 3600 } });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Failed to fetch ${url}`);
  return res.json();
}

async function fetchGaReleases(version: number): Promise<ReleaseAsset[]> {
  const releases: ReleaseAsset[] = [];
  for (let page = 0; ; page++) {
    const batch = await fetchJson<ReleaseAsset[]>(
      `${ADOPTIUM_API}/assets/feature_releases/${version}/ga?vendor=eclipse&page_size=${PAGE_SIZE}&page=${page}`,
    );
    if (!batch) break;
    releases.push(...batch);
    if (batch.length < PAGE_SIZE) break;
  }
  return releases;
}

export function aggregateReleases(
  version: number,
  releases: ReleaseAsset[],
): PlatformBreakdownRow[] {
  const rows = new Map<string, PlatformBreakdownRow>();
  for (const { binaries } of releases) {
    for (const binary of binaries ?? []) {
      const key = `${binary.os}|${binary.architecture}|${binary.image_type}`;
      let row = rows.get(key);
      if (!row) {
        row = {
          version,
          os: binary.os,
          architecture: binary.architecture,
          imageType: binary.image_type,
          archive: 0,
          installer: 0,
        };
        rows.set(key, row);
      }
      row.archive += binary.package?.download_count ?? 0;
      row.installer += binary.installer?.download_count ?? 0;
    }
  }
  return [...rows.values()].filter((row) => row.archive + row.installer > 0);
}

export async function fetchPlatformBreakdown(
  versions: number[],
): Promise<PlatformBreakdownStats> {
  const perVersion = await Promise.all(
    versions.map(async (version) =>
      aggregateReleases(version, await fetchGaReleases(version)),
    ),
  );
  return { rows: perVersion.flat() };
}
